create table if not exists public.ace_student_profiles (user_id uuid primary key references auth.users(id) on delete cascade,full_name text not null default '',institution text,programme text,year_of_study smallint check(year_of_study between 1 and 10),created_at timestamptz not null default now(),updated_at timestamptz not null default now()); alter table public.ace_student_profiles enable row level security; create policy ace_profile_self_read on public.ace_student_profiles for select to authenticated using ((select auth.uid())=user_id);create policy ace_profile_self_insert on public.ace_student_profiles for insert to authenticated with check ((select auth.uid())=user_id);create policy ace_profile_self_update on public.ace_student_profiles for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id);grant select,insert,update on public.ace_student_profiles to authenticated;